/** Point probes share full validation and own their native scratch for exactly one call. */
class PersistentCsfPageCodecProbeTest {

	@ParameterizedTest
	@ValueSource(strings = { "heap", "heap-slice", "heap-readonly", "direct", "direct-slice", "direct-readonly" })
	void everyInputFormPreservesStateAndReturnsDetachedScalars(String form) {
		long[] rows = new long[PersistentCsfPageCodec.MAX_PAIRS];
		long[] neighbors = new long[rows.length];
		long[] contexts = new long[rows.length];
		for (int i = 0; i < rows.length; i++) {
			rows[i] = i / 8 < 64 ? i / 8 : Long.MIN_VALUE + i / 8;
			neighbors[i] = (i % 8) / 2 + 10;
			contexts[i] = i % 2 == 0 ? 0 : Long.MIN_VALUE;
		}
		byte[] encoded = PersistentCsfPageCodec.encode(rows, neighbors, contexts, 0, rows.length);
		Input input = input(encoded, form);
		int position = input.value.position();
		int limit = input.value.limit();
		ByteOrder order = input.value.order();
		input.value.mark();
		List<PersistentCsfPageCodec.ProbeResult> results = new ArrayList<>();
		for (int at : new int[] { 0, rows.length / 2, rows.length - 1 }) {
			results.add(PersistentCsfPageCodec.probe(input.value, rows[at], neighbors[at], contexts[at]));
			assertInputState(input.value, position, limit, order);
			input.value.reset();
			assertThat(input.value.position()).as("probing preserves the caller's mark").isEqualTo(position);
		}
		PersistentCsfPageCodec.ProbeResult absent = PersistentCsfPageCodec.probe(input.value, rows[0], neighbors[0], 1);
		assertInputState(input.value, position, limit, order);
		input.value.reset();
		for (int i = 0; i < encoded.length; i++) {
			input.storage.put(input.offset + i, (byte) 0);
		}
		for (PersistentCsfPageCodec.ProbeResult result : results) {
			assertThat(result.found()).isTrue();
			assertFirstTuple(result, rows[0], neighbors[0], contexts[0]);
		}
		assertThat(absent.found()).isFalse();
		assertFirstTuple(absent, rows[0], neighbors[0], contexts[0]);
	}

	@Test
	void reusingAndFreeingTheSameNativeInputDoesNotRetainProbeState() {
		byte[] first = sample(7);
		byte[] second = sample(70);
		ByteBuffer nativeInput = MemoryUtil.memAlloc(Math.max(first.length, second.length));
		PersistentCsfPageCodec.ProbeResult firstProbe;
		PersistentCsfPageCodec.ProbeResult secondProbe;
		PersistentCsfPageCodec.ProbeResult oldTarget;
		try {
			nativeInput.put(first).flip();
			firstProbe = PersistentCsfPageCodec.probe(nativeInput.asReadOnlyBuffer(), 7, 9, 0);
			nativeInput.clear().put(second).flip();
			secondProbe = PersistentCsfPageCodec.probe(nativeInput.asReadOnlyBuffer(), 70, 10, 1);
			oldTarget = PersistentCsfPageCodec.probe(nativeInput.asReadOnlyBuffer(), 7, 9, 0);
		} finally {
			MemoryUtil.memFree(nativeInput);
		}
		assertThat(firstProbe.found()).isTrue();
		assertFirstTuple(firstProbe, 7, 9, 0);
		assertThat(secondProbe.found()).isTrue();
		assertFirstTuple(secondProbe, 70, 9, 0);
		assertThat(oldTarget.found()).isFalse();
		assertFirstTuple(oldTarget, 70, 9, 0);
	}

	@Test
	void probesFindOnlyExactTuplesAcrossUnsignedBoundaries() {
		long[] rows = { 0, 0, Long.MIN_VALUE, Long.MIN_VALUE, -1, -1 };
		long[] neighbors = { 0, Long.MIN_VALUE, 0, -1, Long.MIN_VALUE, -1 };
		long[] contexts = { 0, -1, Long.MIN_VALUE, 0, -1, -1 };
		ByteBuffer encoded = ByteBuffer.wrap(PersistentCsfPageCodec.encode(rows, neighbors, contexts, 0, rows.length));
		for (int i = 0; i < rows.length; i++) {
			PersistentCsfPageCodec.ProbeResult result = PersistentCsfPageCodec.probe(encoded, rows[i], neighbors[i],
					contexts[i]);
			assertThat(result.found()).as("exact unsigned tuple at ordinal %s", i).isTrue();
			assertFirstTuple(result, 0, 0, 0);
		}
		assertThat(PersistentCsfPageCodec.probe(encoded, 0, 0, 1).found()).isFalse();
		assertThat(PersistentCsfPageCodec.probe(encoded, Long.MIN_VALUE, 1, Long.MIN_VALUE).found()).isFalse();
		assertThat(PersistentCsfPageCodec.probe(encoded, -1, Long.MIN_VALUE, 0).found()).isFalse();
	}

	@ParameterizedTest
	@ValueSource(strings = { "heap-readonly", "direct-slice", "direct-readonly" })
	void malformedEnvelopeOrPayloadPreservesStateAndMatchesDecoderFailure(String form) {
		for (int offset : new int[] { 0, 4, 8, 12, 16, PersistentCsfPageCodec.CHECKSUM_AT, 24,
				PersistentCsfPageCodec.HEADER_BYTES + 160 }) {
			byte[] encoded = sample(7);
			encoded[offset] ^= 1;
			Input input = input(encoded, form);
			int position = input.value.position();
			int limit = input.value.limit();
			ByteOrder order = input.value.order();
			input.value.mark();
			Throwable decoded = catchThrowable(() -> PersistentCsfPageCodec.decode(input.value));
			assertThat(decoded).isInstanceOf(IllegalArgumentException.class);
			assertThatThrownBy(() -> PersistentCsfPageCodec.probe(input.value, 7, 9, 0))
					.as("form=%s, corrupt offset=%s", form, offset)
					.isInstanceOf(IllegalArgumentException.class)
					.hasMessage(decoded.getMessage());
			assertInputState(input.value, position, limit, order);
			input.value.reset();
			assertThat(input.value.position()).isEqualTo(position);
		}
	}

	@Test
	void nativeScratchIsPaddedAndFreedForHitsMissesChecksumAndLateValidationFailures() {
		byte[] valid = sample(7);
		byte[] lateFailure = valid.clone();
		ByteBuffer bytes = ByteBuffer.wrap(lateFailure).order(ByteOrder.LITTLE_ENDIAN);
		int lastNeighbor = PersistentCsfPageCodec.HEADER_BYTES + CompactCsfPageFormat.LAST_NEIGHBOR_AT;
		bytes.putLong(lastNeighbor, bytes.getLong(lastNeighbor) + 1);
		recomputeChecksum(lateFailure);
		byte[] badChecksum = valid.clone();
		badChecksum[badChecksum.length - 1] ^= 1;

		List<Long> sizes = new ArrayList<>();
		Set<Long> owned = new HashSet<>();
		List<Long> released = new ArrayList<>();
		try (MockedStatic<UnsafeAccess> access = mockStatic(UnsafeAccess.class, invocation -> {
			String method = invocation.getMethod().getName();
			if (method.equals("allocate")) {
				long size = invocation.getArgument(0);
				long address = (Long) invocation.callRealMethod();
				sizes.add(size);
				assertThat(owned.add(address)).as("one owner per live native scratch allocation").isTrue();
				return address;
			}
			if (method.equals("free")) {
				long address = invocation.getArgument(0);
				assertThat(owned.remove(address)).as("only owned native scratch is freed").isTrue();
				long tail = address + sizes.getLast() - PackedLongVector.READ_TAIL_PADDING;
				for (int i = 0; i < PackedLongVector.READ_TAIL_PADDING; i++) {
					assertThat(UnsafeAccess.getByte(tail + i)).as("readable tail padding remains zero").isZero();
				}
				released.add(address);
			}
			return invocation.callRealMethod();
		})) {
			assertThat(PersistentCsfPageCodec.probe(input(valid, "direct-readonly").value, 7, 9, 0).found()).isTrue();
			assertThat(PersistentCsfPageCodec.probe(input(valid, "heap-slice").value, 7, 9, 2).found()).isFalse();
			assertThatThrownBy(() -> PersistentCsfPageCodec.probe(input(badChecksum, "direct-slice").value, 7, 9, 0))
					.isInstanceOf(IllegalArgumentException.class)
					.hasMessage("Malformed persistent CSF page: checksum mismatch");
			assertThatThrownBy(() -> PersistentCsfPageCodec.probe(input(lateFailure, "heap-readonly").value, 7, 9, 0))
					.isInstanceOf(IllegalArgumentException.class)
					.hasRootCauseMessage("Malformed persistent CSF page: decoded page does not match the page header");
		}
		long paddedBytes = valid.length - PersistentCsfPageCodec.HEADER_BYTES + PackedLongVector.READ_TAIL_PADDING;
		assertThat(sizes).containsExactly(paddedBytes, paddedBytes, paddedBytes, paddedBytes);
		assertThat(released).hasSize(4);
		assertThat(owned).isEmpty();
	}

	private static void assertFirstTuple(PersistentCsfPageCodec.ProbeResult result, long row, long neighbor,
			long context) {
		assertThat(result.firstRow()).isEqualTo(row);
		assertThat(result.firstNeighbor()).isEqualTo(neighbor);
		assertThat(result.firstContext()).isEqualTo(context);
	}

	private static void assertInputState(ByteBuffer value, int position, int limit, ByteOrder order) {
		assertThat(value.position()).isEqualTo(position);
		assertThat(value.limit()).isEqualTo(limit);
		assertThat(value.order()).isEqualTo(order);
	}

	private static Input input(byte[] encoded, String form) {
		int prefix = 7;
		ByteBuffer storage = form.startsWith("direct") ? ByteBuffer.allocateDirect(encoded.length + 19)
				: ByteBuffer.allocate(encoded.length + 19);
		storage.position(prefix).put(encoded).flip().position(prefix);
		ByteBuffer value = form.endsWith("slice") ? storage.slice() : storage.duplicate();
		if (form.endsWith("readonly")) {
			value = value.asReadOnlyBuffer();
		}
		value.order(ByteOrder.BIG_ENDIAN);
		return new Input(storage, value, prefix);
	}

	private static byte[] sample(long row) {
		return PersistentCsfPageCodec.encode(row, new long[] { 9, 9, 10, 10 }, new long[] { 0, 1, 0, 1 }, 0, 4);
	}

	private static void recomputeChecksum(byte[] encoded) {
		CRC32C checksum = new CRC32C();
		checksum.update(encoded, PersistentCsfPageCodec.HEADER_BYTES,
				encoded.length - PersistentCsfPageCodec.HEADER_BYTES);
		ByteBuffer.wrap(encoded)
				.order(ByteOrder.LITTLE_ENDIAN)
				.putInt(PersistentCsfPageCodec.CHECKSUM_AT, (int) checksum.getValue());
	}

	private record Input(ByteBuffer storage, ByteBuffer value, int offset) {
	}
}
